def write(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text.rstrip()+'\n')

def front(title,description,kind):
    return '---\ntitle: '+json.dumps(title,ensure_ascii=False)+'\ndescription: '+json.dumps(description,ensure_ascii=False)+'\ndiataxis: '+kind+'\n---\n\n# '+title+'\n\n'

def links(case,current):
    d=case['destinations']; labels={'journey':'volte ao caso','explanation':'entenda o mecanismo','tutorial':'execute a experiência','how_to':'resolva a tarefa','reference':'consulte contratos e fontes'}
    return 'Continue o mesmo caso: '+ '; '.join(f'[{labels[k]}]({v})' for k,v in d.items() if k!=current)+'.\n'

def shell_command(case):
    id=case['case_id']
    if id=='date-only':return 'TZ=America/Sao_Paulo node labs/architecture/date-only/run.mjs'
    if id in ['single-flight-cancel','early-refresh','opportunity-entry']:return f'python3 labs/architecture/{id}/run.py'
    return f'python3 labs/architecture/financial.py {id}'

for case in registry['families']:
    id=case['case_id']
    if id not in DETAILS:continue
    d=DETAILS[id];case.update(d)
    command=shell_command(case);case['command']=command
    recorded=receipt_by_case[id];case['recorded_at_utc']=recorded['observed_at_utc']
    extra=list(for_case(id))
    case['additional_model_sources']=sorted({r['source_file'] for r in extra})
    case['additional_observation_count']=len(extra)
    case['invariant_contract_file']='labs/architecture/financial_contracts.json'
    case['execution_gate']='LOCAL_EXECUTION_PASS'
    historical=case['corrected_sha'] is not None
    if historical:
        manifest=json.loads((ROOT/f'labs/architecture/{id}/manifest.json').read_text())
        case['before_sha']=manifest['before_sha'];case['corrected_sha']=manifest['after_sha']
        case['historical_gate']=manifest['historical_lineage_gate']
        source_lines='\n'.join(f'- `{s["source_path"]}` foi preservado em `{s["local_path"]}`, na versão `{s["sha"]}`, com SHA-256 `{s["sha256"]}`.' for s in manifest['snapshots'])
        pr={'single-flight-cancel':51,'early-refresh':51,'date-only':585,'opportunity-entry':594}[id]
        source_path=manifest['snapshots'][0]['source_path']
